import{_ as i,o as a,c as o,ak as t}from"./chunks/framework.Dpc0wyhY.js";const f=JSON.parse('{"title":"Notification Event","description":"","frontmatter":{},"headers":[],"relativePath":"grindr-api/websocket/notification-event.md","filePath":"grindr-api/websocket/notification-event.md"}'),n={name:"grindr-api/websocket/notification-event.md"};function c(d,e,l,r,s,h){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="notification-event" tabindex="-1">Notification Event <a class="header-anchor" href="#notification-event" aria-label="Permalink to “Notification Event”">​</a></h1><p>All notifications include the following fields:</p><ul><li><code>notificationId</code> — UUIDv4 or <code>null</code></li><li><code>ref</code> — always <code>null</code> for notifications</li></ul><h2 id="chat-v1-message-sent" tabindex="-1"><code>chat.v1.message_sent</code> <a class="header-anchor" href="#chat-v1-message-sent" aria-label="Permalink to “chat.v1.message_sent”">​</a></h2><p>Message received, sent, unsent or got reaction.</p><ul><li><em>everything from <a href="#notification-event">Notification Event</a></em></li><li><code>payload</code> — <a href="/grindr-api/messaging/messages#message">Message</a></li></ul><h2 id="chat-v1-refresh-dynamic" tabindex="-1"><code>chat.v1.refresh_dynamic</code> <a class="header-anchor" href="#chat-v1-refresh-dynamic" aria-label="Permalink to “chat.v1.refresh_dynamic”">​</a></h2><p>Album shared, unshared, expiration settings changed or viewed.</p><ul><li><em>everything from <a href="#notification-event">Notification Event</a></em></li><li><code>payload</code> — object <ul><li><code>conversationId</code> — <a href="/grindr-api/messaging/conversations#conversation-id">Conversation ID</a></li><li><code>messageType</code> — <a href="/grindr-api/messaging/messages#message-type">Message Type</a></li></ul></li></ul><h2 id="tap-v1-tap-sent" tabindex="-1"><code>tap.v1.tap_sent</code> <a class="header-anchor" href="#tap-v1-tap-sent" aria-label="Permalink to “tap.v1.tap_sent”">​</a></h2><p>Tap received or sent.</p><ul><li><em>everything from <a href="#notification-event">Notification Event</a></em></li><li><code>payload</code> — object <ul><li><code>timestamp</code></li><li><code>senderId</code></li><li><code>recipientId</code></li><li><code>tapType</code></li><li><code>senderProfileImageHash</code></li><li><code>senderDisplayName</code></li><li><code>isMutual</code></li></ul></li></ul><h2 id="chat-v1-conversation-delete" tabindex="-1"><code>chat.v1.conversation.delete</code> <a class="header-anchor" href="#chat-v1-conversation-delete" aria-label="Permalink to “chat.v1.conversation.delete”">​</a></h2><p>Conversation deleted, e.g. when another profile blocked you. Also fires for unblock events.</p><ul><li><em>everything from <a href="#notification-event">Notification Event</a></em></li><li><code>payload</code> — object <ul><li><code>conversationIds</code> — array of <a href="/grindr-api/messaging/conversations#conversation-id">Conversation ID</a></li></ul></li></ul><h2 id="chat-v1-conversation-read" tabindex="-1"><code>chat.v1.conversation_read</code> <a class="header-anchor" href="#chat-v1-conversation-read" aria-label="Permalink to “chat.v1.conversation_read”">​</a></h2><p>Display read receipt. Sent to all chat participants including yourself reading from another device, check <code>profileId</code> to distinguish.</p><ul><li><em>everything from <a href="#notification-event">Notification Event</a></em></li><li><code>payload</code> — object <ul><li><code>conversationId</code> — <a href="/grindr-api/messaging/conversations#conversation-id">Conversation ID</a></li><li><code>profileId</code> — id of the participant who performed the read, sent as a string</li><li><code>timestamp</code> — unix timestamp in milliseconds; all messages up to and including this time are read by <code>profileId</code></li></ul></li></ul><h2 id="chat-v1-message-deleted" tabindex="-1"><code>chat.v1.message_deleted</code> <a class="header-anchor" href="#chat-v1-message-deleted" aria-label="Permalink to “chat.v1.message_deleted”">​</a></h2><p>Message deleted.</p><ul><li><em>everything from <a href="#notification-event">Notification Event</a></em></li><li><code>payload</code> — WIP</li></ul><h2 id="chat-v1-conversation-update" tabindex="-1"><code>chat.v1.conversation.update</code> <a class="header-anchor" href="#chat-v1-conversation-update" aria-label="Permalink to “chat.v1.conversation.update”">​</a></h2><p>Conversation metadata changed.</p><ul><li><em>everything from <a href="#notification-event">Notification Event</a></em></li><li><code>payload</code> — object <ul><li><code>conversationIds</code> — array of <a href="/grindr-api/messaging/conversations#conversation-id">Conversation ID</a></li></ul></li></ul><h2 id="chat-v1-typing-status" tabindex="-1"><code>chat.v1.typing_status</code> <a class="header-anchor" href="#chat-v1-typing-status" aria-label="Permalink to “chat.v1.typing_status”">​</a></h2><p>Typing indicator changed.</p><ul><li><em>everything from <a href="#notification-event">Notification Event</a></em></li><li><code>payload</code> — object <ul><li><code>conversationId</code> — <a href="/grindr-api/messaging/conversations#conversation-id">Conversation ID</a></li><li><code>profileId</code> — id of the participant whose typing status changed</li><li><code>status</code> — one of <code>Typing</code>, <code>Cleared</code>, <code>Sent</code></li></ul></li></ul><h2 id="chat-v1-cache-bomb-inbox" tabindex="-1"><code>chat.v1.cache_bomb.inbox</code> <a class="header-anchor" href="#chat-v1-cache-bomb-inbox" aria-label="Permalink to “chat.v1.cache_bomb.inbox”">​</a></h2><p>Signals the client to refresh its inbox.</p><ul><li><em>everything from <a href="#notification-event">Notification Event</a></em></li><li><code>payload</code> — WIP</li></ul><h2 id="notification-undelivered" tabindex="-1"><code>notification.undelivered</code> <a class="header-anchor" href="#notification-undelivered" aria-label="Permalink to “notification.undelivered”">​</a></h2><p>WIP</p><h2 id="viewed-me-v1-new-view-received" tabindex="-1"><code>viewed_me.v1.new_view_received</code> <a class="header-anchor" href="#viewed-me-v1-new-view-received" aria-label="Permalink to “viewed_me.v1.new_view_received”">​</a></h2><p>New view received, e.g. when another profile views your profile.</p><ul><li><em>everything from <a href="#notification-event">Notification Event</a></em></li><li><code>payload</code> — object <ul><li><code>viewedCount</code> — total number of profiles that viewed you, including the most recent one</li><li><code>mostRecent</code> — object <ul><li><code>profileId</code> — ID of the profile that viewed</li><li><code>photoHash</code> — hash of the profile photo, if available</li><li><code>timestamp</code> — unix timestamp in milliseconds of the view</li></ul></li></ul></li></ul>',35)])])}const p=i(n,[["render",c]]);export{f as __pageData,p as default};
